    private val cache = arrayOfNulls<Path>(DATA.size)
    private val matrix = Matrix()

    @JvmStatic
    fun count(): Int = DATA.size

    private fun base(index: Int): Path {
        cache[index]?.let { return it }
        val path = Path()
        val pts = DATA[index].split(' ')
        var first = true
        for (p in pts) {
            val c = p.indexOf(',')
            val x = p.substring(0, c).toFloat()
            val y = p.substring(c + 1).toFloat()
            if (first) { path.moveTo(x, y); first = false } else path.lineTo(x, y)
        }
        path.close()
        cache[index] = path
        return path
    }

    /** Fills [out] with shape [index] scaled into [bounds]. */
    @JvmStatic
    fun getPath(index: Int, bounds: RectF, out: Path): Path {
        out.reset()
        if (index < 0 || index >= DATA.size) {
            out.addOval(bounds, Path.Direction.CW)
            return out
        }
        matrix.reset()
        matrix.setScale(bounds.width() / 1000f, bounds.height() / 1000f)
        matrix.postTranslate(bounds.left, bounds.top)
        base(index).transform(matrix, out)
        return out
    }
}
